from dataclasses import dataclass
from pathlib import Path
import ast


@dataclass(slots=True, frozen=True)
class ImportRecord:
    """Immutable record of a single imported module and its local alias."""
    module: str
    alias: str | None


def extract_imports(tree: ast.Module) -> list[ImportRecord]:
    """Extract all imported module names and their assigned local aliases from an AST."""
    records: list[ImportRecord] = []

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                records.append(ImportRecord(module=alias.name, alias=alias.asname))
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            level = node.level
            if level > 0:
                module = f".{module}"
            for alias in node.names:
                records.append(ImportRecord(module=module, alias=alias.asname))

    return sorted(records, key=lambda r: (r.module, r.alias or ""))
```

### Guarantees
- **Zero runtime string parsing**: All module names and aliases are extracted from parsed AST nodes, guaranteeing syntactically valid identifiers.
- **POSIX-compliant paths**: Returns plain module strings (e.g. `os`, `collections.abc`) without platform-specific path separators.
- **Python 3.11+ compliant**: Uses `dataclass(slots=True, frozen=True)` for memory-efficient, hashable records.
